WITH metrics AS (SELECT *, AVG(revenue) OVER w_part last3_avg_revenue, MIN(revenue) OVER w_part last3_min_revenue, MAX(revenue) OVER w_part last3_max_revenue, SUM(revenue) OVER w_part last3_sum_revenue, STDDEV_SAMP(revenue) OVER (PARTITION BY store_id) store_id_stddev_samp_revenue FROM store_sales WINDOW w_part AS (PARTITION BY store_id, product_id ORDER BY sale_date, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW)) SELECT s.id, s.store_id, s.product_id, s.last3_avg_revenue, s.last3_min_revenue, s.last3_max_revenue, s.last3_sum_revenue, s.store_id_stddev_samp_revenue, (SELECT SUM(i2.quantity) FROM inventory i2 WHERE i2.store_id = s.store_id) AS sum_inventory_quantity FROM metrics s ORDER BY product_id DESC;
